"""Tests for datum_local.rules — the phase-scoped rules registry loader."""

from pathlib import Path

from datum_local.rules import (
    MAX_RULES_PER_PHASE,
    load_rules,
    phase_rules,
    render_phase_rules,
)

REGISTRY = Path(__file__).resolve().parent.parent / "rules.toml"


def test_registry_file_exists():
    assert REGISTRY.is_file()


def test_load_rules_returns_entries():
    rules = load_rules()
    assert len(rules) > 10
    assert all("id" in r and "tier" in r and "text" in r for r in rules)


def test_load_rules_missing_file_returns_empty(tmp_path):
    assert load_rules(tmp_path / "nope.toml") == []


def test_phase_rules_act_red():
    rules = phase_rules("act_red")
    assert rules, "act_red should have phase rules"
    assert len(rules) <= MAX_RULES_PER_PHASE
    assert any("assert" in r.lower() for r in rules)


def test_phase_rules_act_green_differs_from_red():
    assert phase_rules("act_green") != phase_rules("act_red")


def test_phase_rules_unknown_phase_empty():
    assert phase_rules("no_such_phase") == []


def test_phase_rules_capped():
    for phase in ("act_red", "act_green", "act_refactor", "review", "plan"):
        assert len(phase_rules(phase)) <= MAX_RULES_PER_PHASE


def test_render_phase_rules_block():
    block = render_phase_rules("act_green")
    assert block.startswith("\nPHASE RULES:")
    assert "- " in block


def test_render_unknown_phase_empty_string():
    assert render_phase_rules("no_such_phase") == ""


def test_guard_tier_documented_not_injected():
    """Guard-tier rules are enforced in code — they must never be injected."""
    guard_texts = {
        r["text"] for r in load_rules() if r.get("tier") == "guard"
    }
    for phase in ("act_red", "act_green", "act_refactor", "review", "plan"):
        for injected in phase_rules(phase):
            assert injected not in guard_texts

